contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        // Ensure the deployer/owner relationship is set by the constructor.
        // We test only the owner-authorised withdrawal to an owner-controlled recipient.
        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;
        assert(balAfter == 0 || recipient != c.owner());
    }

    receive() external payable {}
}

