pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address recipient) internal {
        try c.withdrawAll(recipient) {} catch { return; }
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == 0 || recipient != c.owner());
    }

    function testFuzz_run(address recipient) public {
